#!/usr/bin/env node
'use strict';

/**
 * Exercise payment replay, check-in/refund races and seat release on an isolated database.
 *
 * Prerequisites:
 *   - ticketing_bench has been generated by benchmark_setup.js;
 *   - the bench API on port 3100 is running (REFUND_CUTOFF_HOURS=0);
 *   - this script starts a separate instance on port 3110 for the AC-14 stop/restart test.
 *
 * Output: .cache/benchmarks/transaction-races.json
 */

const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');
const { spawn, spawnSync } = require('node:child_process');
const { createRequire } = require('node:module');

const ROOT = path.join(__dirname, '..');
const SERVER = path.join(ROOT, 'server');
const serverRequire = createRequire(path.join(SERVER, 'package.json'));
const mysql = serverRequire('mysql2/promise');

const BASE = process.env.BENCH_BASE_URL || 'http://127.0.0.1:3100';
const BASE14 = process.env.ANOMALY_BASE_URL || 'http://127.0.0.1:3110';
const DB = process.env.BENCH_DB_NAME || 'ticketing_bench';
const OUT = path.join(ROOT, '.cache', 'benchmarks');
const PASSWORD = 'Demo@1234';

fs.mkdirSync(OUT, { recursive: true });

function delay(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function iso(msFromNow) {
  return new Date(Date.now() + msFromNow).toISOString();
}

function stamp() {
  return new Date().toISOString().replace(/[-:.TZ]/g, '').slice(0, 14);
}

function key(prefix) {
  return `${prefix}-${stamp()}-${crypto.randomBytes(4).toString('hex')}`;
}

function dbConfig() {
  return {
    host: process.env.DB_HOST || '127.0.0.1',
    port: Number.parseInt(process.env.DB_PORT || '3306', 10),
    user: process.env.DB_USER || 'root',
    password: process.env.DB_PASSWORD || '',
    database: DB,
    timezone: 'Z',
  };
}

async function withDb(fn) {
  const conn = await mysql.createConnection(dbConfig());
  try {
    await conn.query("SET SESSION time_zone = '+00:00'");
    return await fn(conn);
  } finally {
    await conn.end();
  }
}

async function apiAt(base, pathname, { method = 'GET', token = null, body = null, idempotencyKey = null, timeoutMs = 30000 } = {}) {
  const headers = {};
  if (token) headers.Authorization = `Bearer ${token}`;
  if (idempotencyKey) headers['Idempotency-Key'] = idempotencyKey;
  if (body !== null) headers['Content-Type'] = 'application/json';
  try {
    const res = await fetch(`${base}${pathname}`, {
      method,
      headers,
      body: body === null ? undefined : JSON.stringify(body),
      signal: AbortSignal.timeout(timeoutMs),
    });
    const text = await res.text();
    let json = null;
    try { json = text ? JSON.parse(text) : null; } catch { /* keep text */ }
    return { status: res.status, json, text };
  } catch (err) {
    return { status: 0, json: null, text: `FETCH_ERROR: ${err.message}` };
  }
}

function api(pathname, opts = {}) {
  return apiAt(BASE, pathname, opts);
}

async function waitHealth(base, attempts = 60) {
  for (let i = 0; i < attempts; i++) {
    const r = await apiAt(base, '/health', { timeoutMs: 2000 });
    if (r.status === 200) return true;
    await delay(500);
  }
  throw new Error(`API not ready: ${base}`);
}

async function login(base, userName) {
  const r = await apiAt(base, '/auth/login', {
    method: 'POST',
    body: { user_name: userName, password: PASSWORD },
    timeoutMs: 30000,
  });
  if (r.status !== 200 || !r.json?.data?.token) {
    throw new Error(`login ${userName} failed: ${r.status} ${r.text.slice(0, 200)}`);
  }
  return r.json.data.token;
}

async function availableSeat(base, performanceId) {
  const r = await apiAt(base, `/performances/${performanceId}/seats`);
  if (r.status !== 200) throw new Error(`seat map ${performanceId}: ${r.status} ${r.text.slice(0, 160)}`);
  const seat = r.json.data.seats.find((s) => s.status === 'AVAILABLE');
  if (!seat) throw new Error(`no AVAILABLE seat on performance ${performanceId}`);
  return seat;
}

async function createPerformance(base, adminToken, { startsAt, saleStartAt, saleEndAt, checkinStartAt, checkinEndAt, eventId = 1, venueId = 1, price = 22000, tag = 'RACE' }) {
  const body = {
    event_id: eventId,
    venue_id: venueId,
    starts_at: startsAt,
    sale_start_at: saleStartAt,
    sale_end_at: saleEndAt,
    checkin_start_at: checkinStartAt,
    checkin_end_at: checkinEndAt,
    price_tiers: [{ tier_name: 'Standard', price_cents: price }],
  };
  const r = await apiAt(base, '/admin/performances', { method: 'POST', token: adminToken, body });
  if (![200, 201].includes(r.status)) throw new Error(`create performance ${tag}: ${r.status} ${r.text.slice(0, 200)}`);
  const performanceId = r.json.data.performance_id;
  const pub = await apiAt(base, `/admin/performances/${performanceId}/publish`, { method: 'POST', token: adminToken });
  if (![200, 201].includes(pub.status)) throw new Error(`publish ${performanceId}: ${pub.status} ${pub.text.slice(0, 160)}`);
  return performanceId;
}

async function createPaidOrder(base, buyerToken, performanceId, seatId, tag) {
  const create = await apiAt(base, '/orders', {
    method: 'POST',
    token: buyerToken,
    idempotencyKey: key(`RACE-${tag}-ORDER`),
    body: { performance_id: performanceId, session_seat_ids: [seatId] },
  });
  if (create.status !== 201) throw new Error(`create order ${tag}: ${create.status} ${create.text.slice(0, 220)}`);
  const orderId = create.json.data.order_id;

  const pay = await apiAt(base, '/payments', {
    method: 'POST',
    token: buyerToken,
    body: { order_id: orderId },
  });
  if (pay.status !== 201) throw new Error(`create payment ${tag}: ${pay.status} ${pay.text.slice(0, 220)}`);
  const paymentId = pay.json.data.payment_id;

  const sim = await apiAt(base, `/payments/${paymentId}/simulate`, {
    method: 'POST',
    token: buyerToken,
    body: { result: 'SUCCESS' },
  });
  if (![200, 201].includes(sim.status)) throw new Error(`simulate ${tag}: ${sim.status} ${sim.text.slice(0, 220)}`);

  const order = await apiAt(base, `/orders/${orderId}`, { token: buyerToken });
  if (order.status !== 200) throw new Error(`get order ${tag}: ${order.status} ${order.text.slice(0, 220)}`);
  const tickets = order.json.data.tickets || [];
  if (!tickets.length) throw new Error(`order ${orderId} has no ticket`);

  const ticketId = tickets[0].ticket_id;
  const ticket = await apiAt(base, `/tickets/${ticketId}`, { token: buyerToken });
  if (ticket.status !== 200) throw new Error(`get ticket ${tag}: ${ticket.status} ${ticket.text.slice(0, 220)}`);
  return {
    order_id: orderId,
    order_no: order.json.data.order_no,
    total_amount_cents: Number(order.json.data.total_amount_cents),
    currency: order.json.data.currency,
    ticket_id: ticketId,
    qr_token: ticket.json.data.qr_token,
    payment_id: paymentId,
    order_status: order.json.data.status,
  };
}

async function snapshot(performanceId, orderIds, seatIds) {
  return withDb(async (conn) => {
    const [orders] = await conn.query(
      `SELECT order_id, status, total_amount, currency, created_at
         FROM orders WHERE order_id IN (${orderIds.join(',')}) ORDER BY order_id`,
    );
    const [tickets] = await conn.query(
      `SELECT t.ticket_id, t.status, oi.order_id
         FROM tickets t JOIN order_items oi ON oi.order_item_id = t.order_item_id
        WHERE oi.order_id IN (${orderIds.join(',')}) ORDER BY t.ticket_id`,
    );
    const [seats] = await conn.query(
      `SELECT session_seat_id, session_seat_status, holder_order_id
         FROM session_seats WHERE session_seat_id IN (${seatIds.join(',')}) ORDER BY session_seat_id`,
    );
    const [checkins] = await conn.query(
      `SELECT c.checkin_id, c.ticket_id, c.checked_in_at, oi.order_id
         FROM checkins c JOIN tickets t ON t.ticket_id = c.ticket_id
         JOIN order_items oi ON oi.order_item_id = t.order_item_id
        WHERE oi.order_id IN (${orderIds.join(',')}) ORDER BY c.checkin_id`,
    );
    const [refunds] = await conn.query(
      `SELECT refund_id, order_id, status, amount, created_at, updated_at
         FROM refunds WHERE order_id IN (${orderIds.join(',')}) ORDER BY refund_id`,
    );
    // Count only orders for this performance so other test orders in the same database are excluded.
    const [perfCounts] = await conn.query(
      `SELECT
         (SELECT COUNT(*) FROM orders WHERE performance_id = ?) AS orders,
         (SELECT COUNT(*) FROM session_seats WHERE performance_id = ?) AS seats,
         (SELECT COUNT(*) FROM session_seats WHERE performance_id = ? AND session_seat_status = 'AVAILABLE') AS available,
         (SELECT COUNT(*) FROM session_seats WHERE performance_id = ? AND session_seat_status = 'SOLD') AS sold,
         (SELECT COUNT(*) FROM session_seats WHERE performance_id = ? AND session_seat_status = 'HELD') AS held`,
      [performanceId, performanceId, performanceId, performanceId, performanceId],
    );
    return { orders, tickets, seats, checkins, refunds, counts: perfCounts[0] };
  });
}

async function caseAc17(adminToken, buyerToken) {
  const perf = await createPerformance(BASE, adminToken, {
    startsAt: iso(2 * 3600 * 1000),
    saleStartAt: iso(-3600 * 1000),
    saleEndAt: iso(90 * 60 * 1000),
    checkinStartAt: iso(-30 * 60 * 1000),
    checkinEndAt: iso(2 * 3600 * 1000),
    price: 21000,
    tag: 'AC17',
  });
  const seat = await availableSeat(BASE, perf);
  const paid = await createPaidOrder(BASE, buyerToken, perf, seat.session_seat_id, 'AC17');

  const checkinKey = key('RACE-AC17-CHK');
  const refundKey = key('RACE-AC17-REF');
  const start = Date.now();
  const [checkin, refund] = await Promise.all([
    api('/admin/checkins', {
      method: 'POST', token: adminToken, idempotencyKey: checkinKey,
      body: { performance_id: perf, ticket_code: paid.qr_token }, timeoutMs: 30000,
    }),
    api(`/orders/${paid.order_id}/refund`, {
      method: 'POST', token: buyerToken, idempotencyKey: refundKey,
      body: { reason: 'AC-17 overlapping check-in and refund' }, timeoutMs: 30000,
    }),
  ]);
  const elapsedMs = Date.now() - start;
  const both = [checkin, refund];
  const success = both.filter((r) => r.status >= 200 && r.status < 300);
  const rejected = both.filter((r) => r.status === 409);
  const serverErrors = both.filter((r) => r.status === 0 || r.status >= 500);
  const state = await snapshot(perf, [paid.order_id], [seat.session_seat_id]);
  const validOutcomes = [
    // Check-in arrives first: ticket USED, order PAID, one check-in
    state.tickets.every((t) => t.status === 'USED') && state.orders[0].status === 'PAID' && state.checkins.length === 1,
    // Refund arrives first: ticket REFUND_PENDING, order REFUND_PENDING, no check-in
    state.tickets.every((t) => t.status === 'REFUND_PENDING') && state.orders[0].status === 'REFUND_PENDING' && state.checkins.length === 0,
  ];
  const pass = success.length === 1 && rejected.length === 1 && serverErrors.length === 0 && validOutcomes.some(Boolean);
  return {
    id: 'AC-17',
    pass,
    performance_id: perf,
    seat_id: seat.session_seat_id,
    order_id: paid.order_id,
    ticket_id: paid.ticket_id,
    checkin: { status: checkin.status, code: checkin.json?.code || null, body: checkin.json },
    refund: { status: refund.status, code: refund.json?.code || null, body: refund.json },
    elapsed_ms: elapsedMs,
    success_count: success.length,
    rejected_409_count: rejected.length,
    server_error_count: serverErrors.length,
    final_state: state,
    valid_outcomes: validOutcomes,
  };
}

async function caseAc24(adminToken, buyerA, buyerB) {
  const perf = await createPerformance(BASE, adminToken, {
    startsAt: iso(3 * 3600 * 1000),
    saleStartAt: iso(-3600 * 1000),
    saleEndAt: iso(2 * 3600 * 1000),
    checkinStartAt: iso(-3600 * 1000),
    checkinEndAt: iso(4 * 3600 * 1000),
    price: 23000,
    tag: 'AC24',
  });
  const seat = await availableSeat(BASE, perf);
  const first = await createPaidOrder(BASE, buyerA, perf, seat.session_seat_id, 'AC24-A');

  const refund = await api(`/orders/${first.order_id}/refund`, {
    method: 'POST', token: buyerA, idempotencyKey: key('RACE-AC24-REF'),
    body: { reason: 'AC-24 refund releases seat' },
  });
  if (refund.status !== 201) throw new Error(`AC-24 refund request: ${refund.status} ${refund.text.slice(0, 220)}`);
  const refundId = refund.json.data.refund_id;
  const resolved = await api(`/admin/refunds/${refundId}/resolve`, {
    method: 'POST', token: adminToken, body: { result: 'SUCCEEDED' },
  });
  if (resolved.status !== 200) throw new Error(`AC-24 resolve: ${resolved.status} ${resolved.text.slice(0, 220)}`);

  const afterRelease = await snapshot(perf, [first.order_id], [seat.session_seat_id]);

  const second = await createPaidOrder(BASE, buyerB, perf, seat.session_seat_id, 'AC24-B');

  const oldCheckin = await api('/admin/checkins', {
    method: 'POST', token: adminToken, idempotencyKey: key('RACE-AC24-OLD-CHK'),
    body: { performance_id: perf, ticket_code: first.qr_token },
  });
  const newCheckin = await api('/admin/checkins', {
    method: 'POST', token: adminToken, idempotencyKey: key('RACE-AC24-NEW-CHK'),
    body: { performance_id: perf, ticket_code: second.qr_token },
  });
  const newCheckinAgain = await api('/admin/checkins', {
    method: 'POST', token: adminToken, idempotencyKey: key('RACE-AC24-NEW-CHK2'),
    body: { performance_id: perf, ticket_code: second.qr_token },
  });

  const finalState = await snapshot(perf, [first.order_id, second.order_id], [seat.session_seat_id]);
  const oldOrder = finalState.orders.find((o) => Number(o.order_id) === first.order_id);
  const newOrder = finalState.orders.find((o) => Number(o.order_id) === second.order_id);
  const oldTicket = finalState.tickets.find((t) => Number(t.ticket_id) === first.ticket_id);
  const newTicket = finalState.tickets.find((t) => Number(t.ticket_id) === second.ticket_id);
  const finalSeat = finalState.seats[0];
  const checks = {
    refund_request_201: refund.status === 201,
    refund_resolve_200: resolved.status === 200,
    seat_released_before_rebuy: afterRelease.seats[0]?.session_seat_status === 'AVAILABLE',
    old_order_stays_refunded: oldOrder?.status === 'REFUNDED',
    new_order_paid: newOrder?.status === 'PAID',
    old_ticket_void: oldTicket?.status === 'VOID',
    new_ticket_used: newTicket?.status === 'USED',
    seat_final_sold: finalSeat?.session_seat_status === 'SOLD',
    old_ticket_checkin_rejected_409: oldCheckin.status === 409,
    new_ticket_checkin_200: newCheckin.status === 200 && newCheckin.json?.data?.result === 'OK',
    new_ticket_second_checkin_rejected_409: newCheckinAgain.status === 409,
    exactly_one_checkin_for_new_ticket: finalState.checkins.filter((c) => Number(c.order_id) === second.order_id).length === 1,
    no_checkin_for_old_ticket: finalState.checkins.filter((c) => Number(c.order_id) === first.order_id).length === 0,
    both_orders_preserved: Boolean(oldOrder && newOrder),
  };
  return {
    id: 'AC-24',
    pass: Object.values(checks).every(Boolean),
    performance_id: perf,
    seat_id: seat.session_seat_id,
    first: first,
    refund_id: refundId,
    refund_resolve: { status: resolved.status, body: resolved.json },
    second: second,
    old_checkin: { status: oldCheckin.status, code: oldCheckin.json?.code || null, body: oldCheckin.json },
    new_checkin: { status: newCheckin.status, code: newCheckin.json?.code || null, body: newCheckin.json },
    new_checkin_again: { status: newCheckinAgain.status, code: newCheckinAgain.json?.code || null, body: newCheckinAgain.json },
    after_release: afterRelease,
    final_state: finalState,
    checks,
  };
}

function sha256(text) {
  return crypto.createHash('sha256').update(text).digest('hex');
}

function startChild(env) {
  const child = spawn(process.execPath, ['src/server.js'], {
    cwd: SERVER,
    env: { ...process.env, ...env },
    stdio: ['ignore', 'pipe', 'pipe'],
  });
  const logs = { out: [], err: [] };
  child.stdout.on('data', (buf) => logs.out.push(buf.toString()));
  child.stderr.on('data', (buf) => logs.err.push(buf.toString()));
  child.on('exit', (code, signal) => {
    logs.exit = { code, signal, at: new Date().toISOString() };
  });
  return { child, logs };
}

async function stopChild(handle) {
  if (!handle || !handle.child || handle.child.exitCode !== null) return;
  const exited = new Promise((resolve) => handle.child.once('exit', resolve));
  handle.child.kill('SIGTERM');
  const ok = await Promise.race([exited.then(() => true), delay(5000).then(() => false)]);
  if (!ok) {
    spawnSync('taskkill', ['/PID', String(handle.child.pid), '/T', '/F'], { stdio: 'ignore' });
    await Promise.race([exited, delay(3000)]);
  }
}

async function caseAc14() {
  await waitHealth(BASE);
  const childEnv = {
    PORT: '3110',
    DB_NAME: DB,
    DB_POOL: '10',
    REFUND_CUTOFF_HOURS: '0',
    RECONCILE_INTERVAL_SECONDS: '2',
    RECONCILE_MIN_AGE_SECONDS: '1',
    RECONCILE_BATCH_SIZE: '50',
  };
  let handle = startChild(childEnv);
  await waitHealth(BASE14);
  const adminToken = await login(BASE14, 'bench_admin');
  const buyerToken = await login(BASE14, 'bench_buyer06');

  const perf = await createPerformance(BASE14, adminToken, {
    startsAt: iso(4 * 3600 * 1000),
    saleStartAt: iso(-3600 * 1000),
    saleEndAt: iso(3 * 3600 * 1000),
    checkinStartAt: iso(-3600 * 1000),
    checkinEndAt: iso(5 * 3600 * 1000),
    price: 25000,
    tag: 'AC14',
  });
  const seat = await availableSeat(BASE14, perf);
  const create = await apiAt(BASE14, '/orders', {
    method: 'POST', token: buyerToken, idempotencyKey: key('RACE-AC14-ORDER'),
    body: { performance_id: perf, session_seat_ids: [seat.session_seat_id] },
  });
  if (create.status !== 201) throw new Error(`AC-14 order: ${create.status} ${create.text.slice(0, 220)}`);
  const orderId = create.json.data.order_id;

  const pay = await apiAt(BASE14, '/payments', {
    method: 'POST', token: buyerToken, body: { order_id: orderId },
  });
  if (pay.status !== 201) throw new Error(`AC-14 payment: ${pay.status} ${pay.text.slice(0, 220)}`);
  const paymentId = pay.json.data.payment_id;
  const order = await apiAt(BASE14, `/orders/${orderId}`, { token: buyerToken });
  const orderNo = order.json.data.order_no;
  const amount = Number(order.json.data.total_amount_cents);

  const notificationId = `REPLAY-${stamp()}-${crypto.randomBytes(3).toString('hex')}`;
  const payload = {
    payment_id: paymentId,
    provider_txn_id: notificationId,
    result: 'SUCCESS',
    amount_cents: amount,
    currency: 'HKD',
    order_no: orderNo,
  };
  const payloadJson = JSON.stringify(payload);
  await withDb(async (conn) => {
    await conn.query(
      `INSERT INTO payment_notifications
         (source, notification_id, payment_attempt_id, received_at, processed_result, payload_digest, payload_json)
       VALUES ('mockpay', ?, ?, UTC_TIMESTAMP(3) - INTERVAL 3 SECOND, 'PENDING', ?, ?)`,
      [notificationId, paymentId, sha256(payloadJson), payloadJson],
    );
  });

  const beforeRestart = await withDb(async (conn) => {
    const [notices] = await conn.query(
      'SELECT notice_id, notification_id, processed_result, processed_at FROM payment_notifications WHERE notification_id = ?',
      [notificationId],
    );
    const [payments] = await conn.query('SELECT attempt_id, result FROM payment_attempts WHERE attempt_id = ?', [paymentId]);
    return { notification: notices[0], payment: payments[0] };
  });

  await stopChild(handle);
  const firstExit = handle?.logs?.exit || null;
  const firstOut = handle?.logs?.out?.slice(-8) || [];
  const firstErr = handle?.logs?.err?.slice(-8) || [];
  await delay(1500);
  handle = startChild(childEnv);
  await waitHealth(BASE14);

  let finalPayment = null;
  let finalOrder = null;
  let finalNotice = null;
  const waits = [];
  for (let i = 0; i < 20; i++) {
    finalPayment = await apiAt(BASE14, `/payments/${paymentId}`, { token: buyerToken });
    finalOrder = await apiAt(BASE14, `/orders/${orderId}`, { token: buyerToken });
    const dbNotice = await withDb(async (conn) => {
      const [rows] = await conn.query(
        'SELECT processed_result, processed_at FROM payment_notifications WHERE notification_id = ?',
        [notificationId],
      );
      return rows[0];
    });
    finalNotice = dbNotice;
    waits.push({
      second: (i + 1) * 0.5,
      payment_status: finalPayment.json?.data?.status || null,
      order_status: finalOrder.json?.data?.status || null,
      notice_result: finalNotice?.processed_result || null,
    });
    if (finalPayment.status === 200 && finalPayment.json?.data?.status === 'SUCCEEDED' &&
        finalOrder.status === 200 && finalOrder.json?.data?.status === 'PAID' &&
        finalNotice?.processed_result === 'APPLIED') {
      break;
    }
    await delay(500);
  }

  const afterRestart = await snapshot(perf, [orderId], [seat.session_seat_id]);
  const checks = {
    notification_pending_before_restart: beforeRestart.notification?.processed_result === 'PENDING',
    payment_pending_before_restart: beforeRestart.payment?.result === 'PENDING',
    process_restarted: Boolean(firstExit),
    payment_succeeded_after_restart: finalPayment?.json?.data?.status === 'SUCCEEDED',
    order_paid_after_restart: finalOrder?.json?.data?.status === 'PAID',
    notification_applied: finalNotice?.processed_result === 'APPLIED',
    exactly_one_ticket: (afterRestart.tickets || []).length === 1,
    seat_sold: afterRestart.seats?.[0]?.session_seat_status === 'SOLD',
  };
  return {
    id: 'AC-14',
    pass: Object.values(checks).every(Boolean),
    performance_id: perf,
    seat_id: seat.session_seat_id,
    order_id: orderId,
    payment_id: paymentId,
    notification_id: notificationId,
    before_restart: beforeRestart,
    after_restart: {
      payment_status: finalPayment?.json?.data?.status,
      order_status: finalOrder?.json?.data?.status,
      notice_result: finalNotice?.processed_result,
      ticket_count: (afterRestart.tickets || []).length,
      state: afterRestart,
    },
    poll: waits,
    checks,
    child_logs: {
      first_out_tail: firstOut,
      first_err_tail: firstErr,
      first_exit: firstExit,
      final_exit: handle?.logs?.exit,
    },
  };
  // The port 3110 instance is cleaned up by main finally block using the port.
}

async function main() {
  const t0 = Date.now();
  await waitHealth(BASE);
  const adminToken = await login(BASE, 'bench_admin');
  const buyer17 = await login(BASE, 'bench_buyer02');
  const buyer24a = await login(BASE, 'bench_buyer03');
  const buyer24b = await login(BASE, 'bench_buyer04');

  const results = [];
  try {
    results.push(await caseAc17(adminToken, buyer17));
    results.push(await caseAc24(adminToken, buyer24a, buyer24b));
    results.push(await caseAc14());
  } finally {
    // Clean up the port 3110 test instance (caseAc14 already returned; the handle is not here, so fall back to the port).
    const conn = spawnSync('netstat', ['-ano', '-p', 'tcp'], { encoding: 'utf8' });
    const line = (conn.stdout || '').split(/\r?\n/).find((l) => l.includes(':3110') && l.includes('LISTENING'));
    if (line) {
      const pid = line.trim().split(/\s+/).pop();
      if (pid && pid !== '0') spawnSync('taskkill', ['/PID', pid, '/T', '/F'], { stdio: 'ignore' });
    }
  }

  const payload = {
    captured_at: new Date().toISOString(),
    base_url: BASE,
    database: DB,
    elapsed_ms: Date.now() - t0,
    cases: results,
    all_pass: results.every((c) => c.pass),
  };
  fs.writeFileSync(path.join(OUT, 'transaction-races.json'), JSON.stringify(payload, null, 2) + '\n', 'utf8');
  console.log(`[anomalies] all_pass=${payload.all_pass}`);
  for (const c of results) console.log(`  ${c.id} pass=${c.pass}`);
  if (!payload.all_pass) process.exitCode = 2;
}

main().catch((err) => {
  console.error('[FAIL]', err.stack || err.message);
  process.exit(1);
});
